def _paused(self, sid: str) -> bool:
    try:
        return self.sandboxes.get(sid)["status"] == "paused"
    except SandboxError:
        return False

def reset_gui_state(self, sid: str) -> None:
    self._gui_input_at.pop(sid, None)
    self._gui_snap_at.pop(sid, None)

def end_gui_burst(self, sid: str, reason: str) -> None:
    self._close_gui_burst(sid, reason)   # container still runs: stop strays, log gui_changes
    self.reset_gui_state(sid)            # next GUI input opens a fresh burst (snapshot + baseline)

# _gui_needs_snapshot: right after the gui_snapshot_interval <= 0 check
if self._paused(sid):
    return False                         # the tool fails anyway; do not touch burst state

# close_idle_gui_bursts: inside the idle test, before _close_gui_burst(sid, "idle")
if self._paused(sid):
    continue                             # cannot enforce on a frozen container; close after resume

# end_desktop: replace self._close_gui_burst(sid, reason) with
self.end_gui_burst(sid, reason)

@app.post("/sandboxes/{sid}/pause")
def pause(sid: str, p: Principal = Depends(human_only)):
    box.log_human("sandbox_pause", sid, {})
    box.end_gui_burst(sid, "sandbox_paused")   # close the burst while the container still runs
    guard(lambda: box.sandboxes.pause(sid))
    return box.sandboxes.get(sid)
